#
# t_phase4.jl
#
# To compare the VIE2 solvers, the bubble diagrams, and the density matrix
# with NESSi, point by point. The data are generated by
# .nessi/kbref/phase4_{vie2,bubble,observables}.cpp, whose closed-form
# inputs are rebuilt here with exactly the same formulas (nothing is read
# back from the output).
#
# NESSi reference: libcntr/cntr/cntr_vie2_impl.hpp, cntr_bubble_impl.hpp,
# and cntr_herm_matrix_impl.hpp (density_matrix).
#
# Primary gate: every entry with atol = rtol = 1e-10. The scalars of the
# CG trajectory are also checked with an absolute error < 1e-12 (relative
# to their magnitude).
#
# The large embedding cases of libcntr/test/dyson.cpp and dyson_new.cpp
# (nt = 200, ntau = 400) run in the release profile only.
#

isdefined(Main, :kb_test_profile) ||
    include(joinpath(@__DIR__, "common", "profile.jl"))

using LinearAlgebra

const P4_DATA = joinpath(@__DIR__, "data", "phase4")

#
# Non-commuting 2x2 case, see phase4_vie2.cpp
#
const P4_NT = 20
const P4_NTAU = 40
const P4_BETA = 2.0
const P4_H = 0.05
const P4_MU = 0.2
const P4_AMP = 0.2

p4_f_mat(τ) = P4_AMP * C64[-0.5*exp(-τ) 0.2+0.1im*τ/P4_BETA;
                           -0.15+0.05im -0.3*exp(-0.5τ)]
p4_f_ret(t, t′) = P4_AMP * C64[-im*cos(t-t′) 0.2*exp(-im*(t-0.5t′));
                               -0.1+0.3im*sin(t+t′) -0.5im*exp(-0.3(t-t′))]
p4_f_tv(t, τ) = P4_AMP * C64[0.3im*exp(-τ)*cos(t) 0.1+0.2im*t;
                             -0.2*exp(-0.5τ) 0.4im*sin(t+τ)]
p4_f_les(t′, t) = P4_AMP * C64[0.2im*cos(t-t′) 0.1+0.1im*t′;
                               -0.3+0.05im*t 0.25im]
p4_fcc_mat(τ) = P4_AMP * C64[0.4*exp(-τ) -0.1+0.2im; 0.3im*τ/P4_BETA -0.25]
p4_fcc_ret(t, t′) = P4_AMP * C64[0.5im*sin(t-t′)-0.3 0.1*exp(im*t′);
                                 0.2im -0.4*cos(t+t′)]
p4_fcc_tv(t, τ) = P4_AMP * C64[0.2*cos(t)*exp(-τ) 0.1im*τ;
                               -0.3+0.1im*t 0.2*exp(-0.5τ)]
p4_fcc_les(t′, t) = P4_AMP * C64[0.1im 0.2*cos(t)+0.1im; -0.1*t′ 0.3im*sin(t′)]

function p4_kernel!(X::ℱ, cc::Bool)
    δτ = P4_BETA / P4_NTAU
    fm, fr, ft, fl = cc ? (p4_fcc_mat, p4_fcc_ret, p4_fcc_tv, p4_fcc_les) :
                          (p4_f_mat, p4_f_ret, p4_f_tv, p4_f_les)
    for q = 0:P4_NTAU
        X.mat[q+1] = fm(q * δτ)
    end
    for i = 0:P4_NT
        for j = 0:i
            X.ret[i+1, j+1] = fr(i * P4_H, j * P4_H)
        end
        for q = 0:P4_NTAU
            X.lmix[i+1, q+1] = ft(i * P4_H, q * δτ)
        end
        for j = i:P4_NT
            X.less[i+1, j+1] = fl(i * P4_H, j * P4_H)
        end
    end
    return X
end

function p4_nc_build(sign)
    C = Cn(P4_NT + 1, P4_NTAU + 1, 2, 2, P4_NT * P4_H, P4_BETA)
    F = p4_kernel!(ℱ(C, sign), false)
    Fcc = p4_kernel!(ℱ(C, sign), true)
    HQ = C64[0.5 0.3-0.2im; 0.3+0.2im -0.4]
    sign == BOSE && (HQ = HQ + 1.5 * I)
    Q = ℱ(C, sign)
    from_ham!(Q, P4_MU, HQ, P4_BETA, P4_H)
    return C, F, Fcc, Q
end

function p4_read(name)
    ref = read_kbref(joinpath(P4_DATA, name * ".dat"))
    @test ref.metadata["case"] == name
    return ref
end

function p4_report(name, errs)
    @printf("  %-40s max err: mat %.2e ret %.2e tv %.2e les %.2e\n",
            name, errs["mat"], errs["ret"], errs["tv"], errs["les"])
end

#
# Embedding model of libcntr/test/dyson.cpp and dyson_new.cpp
#
function p4_embedding(name, μ, β, method)
    nt, ntau, k, h = 200, 400, 5, 0.05
    eps1, eps2, lam = -1.0, 1.0, 0.2
    C = Cn(nt + 1, ntau + 1, 1, 1, nt * h, β)
    H = Cf(nt + 1, 1, 1)
    for n = 0:nt+1
        H[n] = fill(C64(eps1), 1, 1)
    end
    S = ℱ(C, FERMI)
    from_ham!(S, μ, fill(C64(eps2), 1, 1), β, h)
    for t = 0:nt+1
        smul!(S, t, lam^2)
    end
    G0 = ℱ(C, FERMI)
    from_ham!(G0, μ, fill(C64(eps1), 1, 1), β, h)
    G = ℱ(C, FERMI)
    dyson_mat!(G, S, μ, H, β; solve_order = k, method = method)
    F = ℱ(C, FERMI)
    Fcc = ℱ(C, FERMI)
    convolution(F, G0, S, k, β, h)
    convolution(Fcc, S, G0, k, β, h)
    for t = 0:nt+1
        smul!(F, t, -1.0)
        smul!(Fcc, t, -1.0)
    end
    I5 = Integrator(k)
    vie2_start!(G, F, Fcc, G0, I5, β, h)
    for tstp = k+2:nt+1
        vie2_timestep!(tstp, G, F, Fcc, G0, I5, β, h)
    end
    ref = p4_read(name)
    p4_report(name, test_kbref(G, ref))
    # Aggregate check of the Catch test, err / Nt < 1e-6
    G2 = ℱ(Cn(nt + 1, ntau + 1, 2, 2, nt * h, β), FERMI)
    from_ham!(G2, μ, C64[eps1 im*lam; -im*lam eps2], β, h)
    Gx = ℱ(C, FERMI)
    for m = 1:ntau+1
        Gx.mat[m] = G2.mat[m][1:1, 1:1]
    end
    for i = 1:nt+1
        for m = 1:ntau+1
            Gx.lmix[i, m] = G2.lmix[i, m][1:1, 1:1]
        end
        for j = 1:i
            Gx.ret[i, j] = G2.ret[i, j][1:1, 1:1]
            Gx.less[j, i] = G2.less[j, i][1:1, 1:1]
        end
    end
    err = sum(distance(Gx, G, n) for n = 0:nt+1)
    @test err / nt < 1e-6
end

#
# Interacting section of libcntr/test/downfold.cpp
#
function p4_downfold()
    nt, ntau, k, β, h = 20, 300, 5, 1.0, 0.01
    a = C64[1 1 1; 1 2 1; 1 1 3]
    C = Cn(nt + 1, ntau + 1, 3, 3, nt * h, β)
    S = ℱ(C, FERMI)
    G0 = ℱ(C, FERMI)
    from_ham!(S, 0.0, a, β, h)
    from_ham!(G0, 0.0, a, β, h)
    F = ℱ(C, FERMI)
    Fcc = ℱ(C, FERMI)
    convolution(F, G0, S, k, β, h)
    convolution(Fcc, S, G0, k, β, h)
    for t = 0:nt+1
        smul!(F, t, -1.0)
        smul!(Fcc, t, -1.0)
    end
    G = ℱ(C, FERMI)
    vie2!(G, F, Fcc, G0, Integrator(k), β, h)
    name = "phase4_vie2_downfold_size3"
    p4_report(name, test_kbref(G, p4_read(name)))
end

#
# Bubble diagrams, see phase4_bubble.cpp
#
function p4_bubble(bubble, size, sa, sb)
    nt, ntau, β, h = 10, 20, 2.0, 0.1
    HA = C64[0.4 0.3-0.2im; 0.3+0.2im -0.6][1:size, 1:size]
    HB = C64[1.2 0.1im; -0.1im 1.9][1:size, 1:size]
    C = Cn(nt + 1, ntau + 1, size, size, nt * h, β)
    A = ℱ(C, sa)
    B = ℱ(C, sb)
    from_ham!(A, sa == FERMI ? 0.1 : -0.5, HA, β, h)
    from_ham!(B, sb == FERMI ? 0.2 : -0.3, HB, β, h)
    X = ℱ(C, sa * sb)
    for tstp = 0:nt+1, c1 = 1:size, c2 = 1:size
        if bubble == 1
            bubble1!(tstp, X, c1, c2, A, c1, c2, B, c2, c1)
        else
            bubble2!(tstp, X, c1, c2, A, c1, c2, B, c1, c2)
        end
    end
    tag(s) = s == FERMI ? "f" : "b"
    name = "phase4_bubble$(bubble)_$(tag(sa))$(tag(sb))_size$(size)"
    ref = p4_read(name)
    @test parse(Int, ref.metadata["signA"]) == sa
    @test parse(Int, ref.metadata["signB"]) == sb
    @test parse(Int, ref.metadata["sig"]) == sa * sb
    p4_report(name, test_kbref(X, ref))
end

@testset verbose = true "NESSi: phase 4" begin
    @testset "VIE2 non-commuting 2x2 (k = $k)" for k = 1:5
        C, F, Fcc, Q = p4_nc_build(FERMI)
        G = ℱ(C, FERMI)
        vie2!(G, F, Fcc, Q, Integrator(k), P4_BETA, P4_H)
        name = "phase4_vie2_ncomm_size2_k$k"
        ref = p4_read(name)
        @test parse(Int, ref.metadata["solve_order"]) == k
        p4_report(name, test_kbref(G, ref))
    end

    @testset "VIE2 non-commuting 2x2 (bosons)" begin
        C, F, Fcc, Q = p4_nc_build(BOSE)
        G = ℱ(C, BOSE)
        vie2!(G, F, Fcc, Q, Integrator(5), P4_BETA, P4_H)
        name = "phase4_vie2_ncomm_boson_size2_k5"
        p4_report(name, test_kbref(G, p4_read(name)))
    end

    @testset "VIE2 time step routing" begin
        for (sign, last) in ((FERMI, 0), (FERMI, 2), (BOSE, 0))
            C, F, Fcc, Q = p4_nc_build(sign)
            G = ℱ(C, sign)
            # NESSi n = -1, ⋯, last is KB tstp = 0, ⋯, last + 1
            for tstp = 0:last+1
                vie2_timestep!(tstp, G, F, Fcc, Q, Integrator(5), P4_BETA, P4_H)
            end
            name = "phase4_vie2_route_$(sign == FERMI ? "fermion" : "boson")_n$last"
            p4_report(name, test_kbref(G, p4_read(name)))
        end
    end

    @testset "VIE2 singular kernel" begin
        p4_fsin(t) = C64[0.3+0.1*sin(t) 0.1im+0.05*t; -0.1im+0.05*t -0.2]
        p4_qsin(t) = C64[0.5 0.2+0.1im*t; -0.3*cos(t) -0.4+0.1*t]
        for (sign, k) in ((FERMI, 3), (FERMI, 5), (BOSE, 5))
            C, F, Fcc, Q = p4_nc_build(sign)
            nt = P4_NT + 1
            Fs = Cf(nt, 2, 2)
            Qs = Cf(nt, 2, 2)
            Gs = Cf(nt, 2, 2)
            # KB Cf[0] is the Matsubara value (NESSi n = -1, t = 0)
            Fs[0] = p4_fsin(0.0)
            Qs[0] = p4_qsin(0.0)
            for i = 1:nt
                Fs[i] = p4_fsin((i - 1) * P4_H)
                Qs[i] = p4_qsin((i - 1) * P4_H)
            end
            G = ℱ(C, sign)
            Ik = Integrator(k)
            for tstp = 0:nt
                vie2_timestep_sin!(tstp, G, Gs, F, Fcc, Fs, Q, Qs, Ik, P4_BETA, P4_H)
            end
            name = "phase4_vie2_sin_$(sign == BOSE ? "boson_" : "")size2_k$k"
            p4_report(name, test_kbref(G, p4_read(name)))
            # Singular part, closed form
            @test maximum(norm(Gs[i] - (Matrix{C64}(I, 2, 2) + Fs[i]) \ Qs[i]) for i = 0:nt) < 1e-14
        end
    end

    @testset "VIE2 start-up lesser source blocks" begin
        k = 5
        I5 = Integrator(k)
        C, F, Fcc, Q = p4_nc_build(FERMI)
        G = ℱ(C, FERMI)
        vie2_mat!(G, F, Fcc, Q, P4_BETA, I5)
        vie2_start!(G, F, Fcc, Q, I5, P4_BETA, P4_H)
        ref = p4_read("phase4_vie2_start_less_source_size2")
        @test ref.metadata["data_kind"] == "element"
        ws = KadanoffBaym._ConvWorkspace(F.ret.data, G.ret.data)
        bufs = Dict{Tuple{String,Int},Vector{Matrix{C64}}}()
        for n = 0:k-1
            b₁ = [zeros(C64, 2, 2) for _ = 1:k+1]
            b₂ = [zeros(C64, 2, 2) for _ = 1:k+1]
            KadanoffBaym._incr_convolution_lmix_rmix!(b₁, n + 1, F, Fcc, nothing, G, G,
                                                      I5, P4_BETA, P4_H, one(C64), ws)
            KadanoffBaym._incr_convolution_less_adv!(b₂, n + 1, F, Fcc, nothing, G, G,
                                                     I5, P4_BETA, P4_H, one(C64), ws)
            bufs[("startup_lmix_rmix", n)] = b₁
            bufs[("startup_less_adv", n)] = b₂
        end
        nfail = 0
        err = 0.0
        njn = 0
        for row in ref.rows
            v = bufs[(row.component, row.i)][row.j+1][row.a+1, row.b+1]
            err = max(err, abs(v - row.value))
            isapprox(v, row.value; atol = 1e-10, rtol = 1e-10) || (nfail += 1)
            row.j > row.i && (njn += 1)
        end
        @test nfail == 0
        # The blocks j > n (including n = k - 1, j = k) are present
        @test njn == 2 * 4 * sum(k - n for n = 0:k-1)
        @test length(ref.rows) == 2 * 4 * k * (k + 1)
        @printf("  %-40s max err: %.2e\n", "phase4_vie2_start_less_source_size2", err)
    end

    @testset "VIE2 FIXPOINT trajectory" begin
        I5 = Integrator(5)
        C, F, Fcc, Q = p4_nc_build(FERMI)
        ref = p4_read("phase4_vie2_fixpoint_trajectory_size2")
        @test ref.metadata["algorithm"] == "fixpoint"
        niter = parse(Int, ref.metadata["niter"])
        @test niter == 6
        Gs = Dict{Int,ℱ}()
        for nf = 0:niter
            G = ℱ(C, FERMI)
            KadanoffBaym._vie2_mat_fixpoint!(G, F, Q, P4_BETA, I5; nfixpoint = nf)
            Gs[nf] = G
        end
        nfail = 0
        err = 0.0
        for row in ref.rows
            v = Gs[row.i].mat[row.j+1][row.a+1, row.b+1]
            err = max(err, abs(v - row.value))
            isapprox(v, row.value; atol = 1e-10, rtol = 1e-10) || (nfail += 1)
        end
        @test nfail == 0
        @test length(ref.rows) == (niter + 1) * (P4_NTAU + 1) * 4
        @printf("  %-40s max err: %.2e\n", "phase4_vie2_fixpoint_trajectory_size2", err)
    end

    @testset "VIE2 CG trajectory" begin
        I5 = Integrator(5)
        C, F, Fcc, Q = p4_nc_build(FERMI)
        ref = p4_read("phase4_vie2_cg_trajectory_size2")
        @test ref.metadata["algorithm"] == "cg"
        niter = parse(Int, ref.metadata["niter"])
        G = ℱ(C, FERMI)
        trace = []
        n = KadanoffBaym._vie2_mat_cg!(G, F, Fcc, Q, P4_BETA, I5;
                                       maxiter = 40, tol = 1e-12, trace = trace)
        @test n == niter
        @test length(trace) == niter
        key = Dict("rsold" => :rsold, "c2" => :c2, "alpha" => :alpha,
                   "rsnew" => :rsnew, "beta_cg" => :beta)
        nfail = 0
        errg = 0.0
        errs = 0.0
        for row in ref.rows
            rec = trace[row.i]
            if row.component == "g"
                v = rec.G[row.a+1, row.b+1, row.j+1]
                errg = max(errg, abs(v - row.value))
                isapprox(v, row.value; atol = 1e-10, rtol = 1e-10) || (nfail += 1)
            else
                v = getfield(rec, key[row.component])
                e = abs(v - real(row.value))
                errs = max(errs, e / max(1.0, abs(real(row.value))))
                e ≤ 1e-12 * max(1.0, abs(real(row.value))) || (nfail += 1)
            end
        end
        @test nfail == 0
        @printf("  %-40s max err: g %.2e scalars %.2e (%d iterations)\n",
                "phase4_vie2_cg_trajectory_size2", errg, errs, niter)
        #
        # The trace inner product gives a different first step
        X = ℱ(C, FERMI)
        KadanoffBaym._matsubara_seed!(X.mat, F.mat, Q.mat, P4_BETA, FERMI; pcf = 3)
        R = KadanoffBaym.Gᵐᵃᵗ(P4_NTAU + 1, 2, 2)
        C₁ = KadanoffBaym.Gᵐᵃᵗ(P4_NTAU + 1, 2, 2)
        C₂ = KadanoffBaym.Gᵐᵃᵗ(P4_NTAU + 1, 2, 2)
        KadanoffBaym.conv_mat(C₁, F.mat, X.mat, I5, P4_BETA, FERMI)
        KadanoffBaym.conv_mat(C₂, X.mat, Fcc.mat, I5, P4_BETA, FERMI)
        R.data .= Q.mat.data .- (0.5 .* (C₁.data .+ C₂.data) .+ X.mat.data)
        rs_full = KadanoffBaym._mat_inner(R, R, I5)
        @test abs(rs_full - trace[1].rsold) ≤ 1e-12 * max(1.0, abs(rs_full))
        N = P4_NTAU
        w(r) = r ≤ 5 ? I5.GIW.ω[r+1] : (r ≥ N - 5 ? I5.GIW.ω[N-r+1] : 1.0)
        rs_trace = sum(w(r) * real(tr(R.data[:, :, r+1]' * R.data[:, :, r+1])) for r = 0:N)
        @test abs(rs_trace - trace[1].rsold) > 1e-6 * abs(trace[1].rsold)
    end

    @testset "VIE2 downfold (3x3)" begin
        p4_downfold()
    end

    if kb_release()
        @testset "release: VIE2 embedding (dyson.cpp, dyson_new.cpp)" begin
            @test kb_test_profile() == "release"
            p4_embedding("phase4_vie2_dyson_size1", -0.1, 10.0, :fixpoint)
            p4_embedding("phase4_vie2_dyson_new_size1", 0.0, 20.0, :cg)
        end
    end

    @testset "Bubble $(bubble) size $(size)" for bubble = 1:2, size = 1:2
        for sa in (FERMI, BOSE), sb in (FERMI, BOSE)
            p4_bubble(bubble, size, sa, sb)
        end
    end

    @testset "density matrix" begin
        nt, ntau, β, h = 8, 16, 3.0, 0.1
        Hb = C64[1.2 0.3-0.2im; 0.3+0.2im 1.8]
        C = Cn(nt + 1, ntau + 1, 2, 2, nt * h, β)
        for (name, sign) in (("phase4_observables_density_equilibrium", BOSE),
                             ("phase4_observables_density_realtime", FERMI))
            G = ℱ(C, sign)
            if sign == BOSE
                from_ham!(G, -0.4, Hb, β, h)
            else
                from_ham!(G, 0.1, Hb - 1.5 * I, β, h)
            end
            ref = p4_read(name)
            @test ref.metadata["data_kind"] == "element"
            @test parse(Int, ref.metadata["sig"]) == sign
            nfail = 0
            err = 0.0
            for row in ref.rows
                @test row.component == "density_matrix"
                v = density_matrix(G, row.j + 1)[row.a+1, row.b+1]
                err = max(err, abs(v - row.value))
                isapprox(v, row.value; atol = 1e-10, rtol = 1e-10) || (nfail += 1)
            end
            @test nfail == 0
            @test length(ref.rows) == (sign == BOSE ? 4 : 4 * (nt + 1))
            @printf("  %-40s max err: %.2e\n", name, err)
        end
    end
end
